{"command":"Set-Location .\binlog-analyzer; @'
using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

static string Clean(string? s) => (s ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
static string ShortPath(string? p)
{
    if (string.IsNullOrWhiteSpace(p)) return "";
    var s = p.Replace('/', '\\');
    var idx = s.LastIndexOf("\\src\\", StringComparison.OrdinalIgnoreCase);
    if (idx >= 0) return s.Substring(idx + 1);
    idx = s.LastIndexOf("\\test\\", StringComparison.OrdinalIgnoreCase);
    if (idx >= 0) return s.Substring(idx + 1);
    var parts = s.Split('\\', StringSplitOptions.RemoveEmptyEntries);
    return parts.Length > 4 ? string.Join('\\', parts.Skip(parts.Length - 4)) : s;
}

var path = args.Length > 0 ? args[0] : @"..\build.binlog";
var build = BinaryLog.ReadBuild(path);
build.WaitForBackgroundTasks();
Console.WriteLine($"Build succeeded: {build.Succeeded}; MSBuild: {build.MSBuildVersion}; FirstError: {Clean(build.FirstError?.ToString())}");
var errors = build.FindChildrenRecursive(n => n is Error).Cast<Error>().ToList();
var warnings = build.FindChildrenRecursive(n => n is Warning).Cast<Warning>().ToList();
Console.WriteLine($"Errors: {errors.Count}; Warnings: {warnings.Count}");
Console.WriteLine("---ERRORS---");
int i = 0;
foreach (var e in errors)
{
    var project = e.GetNearestParentOrSelf<Project>();
    var target = e.GetNearestParentOrSelf<Target>();
    var task = e.GetNearestParentOrSelf<Microsoft.Build.Logging.StructuredLogger.Task>();
    Console.WriteLine($"#{++i}");
    Console.WriteLine($"Time: {e.Timestamp:O}");
    Console.WriteLine($"Code: {e.Code}");
    Console.WriteLine($"Project: {ShortPath(e.ProjectFile ?? project?.ProjectFile)}");
    Console.WriteLine($"ProjectFull: {e.ProjectFile ?? project?.ProjectFile}");
    Console.WriteLine($"Target: {target?.Name}");
    Console.WriteLine($"Task: {task?.Name}");
    Console.WriteLine($"File: {ShortPath(e.File)}");
    Console.WriteLine($"Line: {e.LineNumber}; Column: {e.ColumnNumber}");
    Console.WriteLine($"Text: {Clean(e.Text)}");
    Console.WriteLine($"String: {Clean(e.ToString())}");
    Console.WriteLine($"ParentChain: {string.Join(" > ", e.GetParentChainIncludingThis().Reverse().Select(n => n.GetType().Name + ":" + Clean((n as NamedNode)?.Name ?? (n as TextNode)?.Text ?? n.Title)).TakeLast(8))}");
}
Console.WriteLine("---PROJECTS---");
foreach (var p in build.FindChildrenRecursive(n => n is Project).Cast<Project>().OrderBy(p=>p.StartTime))
{
    var perrs = p.FindChildrenRecursive(n => n is Error).Count;
    var status = p.FindChildrenRecursive(n => n is Target t && !t.Succeeded).Any() || perrs>0 ? "has-errors" : "ok";
    if (perrs>0 || p.Name.EndsWith(".sln", StringComparison.OrdinalIgnoreCase))
        Console.WriteLine($"{p.StartTime:O}\t{status}\tErrors={perrs}\tProject={ShortPath(p.ProjectFile)}\tName={p.Name}\tTFM={p.TargetFramework}\tTargets={p.TargetsText}");
}
'@ | Set-Content -Path .\Program.cs -Encoding UTF8; dotnet run --no-restore --tl:off -- ..\build.binlog | Tee-Object -FilePath .\errors.txt","description":"Extract binlog errors and project contexts","initial_wait":120}
